import React from "react";
import { Helmet } from "react-helmet";

const SITE_URL  = "https://arshanaslam.me";
const OG_IMAGE  = `${SITE_URL}/og_image.png`;
const TWITTER   = "@arshanaslam";

export default function SEO({ title, description, path = "" }) {
  const fullTitle = title
    ? `${title} — Arshan Aslam`
    : "Arshan Aslam — AI Engineer & Full-Stack Developer";

  const fullDesc = description ||
    "Software engineer with 5+ years building production AI systems — RAG pipelines, multi-agent workflows, and cloud-native backends. Available for freelance AI engineering.";

  const canonical = `${SITE_URL}${path}`;

  return (
    <Helmet>
      {/* ── Primary ──────────────────────────────────────────── */}
      <title>{fullTitle}</title>
      <meta name="description" content={fullDesc} />
      <meta name="keywords" content="AI engineer, full-stack developer, RAG, LangChain, Django, React, Python, freelance AI, Lahore Pakistan, LLM, vector database, FastAPI" />
      <meta name="author" content="Arshan Aslam" />
      <link rel="canonical" href={canonical} />

      {/* ── Open Graph ───────────────────────────────────────── */}
      <meta property="og:type"        content="website" />
      <meta property="og:url"         content={canonical} />
      <meta property="og:title"       content={fullTitle} />
      <meta property="og:description" content={fullDesc} />
      <meta property="og:image"       content={OG_IMAGE} />
      <meta property="og:image:width"  content="1200" />
      <meta property="og:image:height" content="630" />
      <meta property="og:site_name"   content="Arshan Aslam" />
      <meta property="og:locale"      content="en_US" />

      {/* ── Twitter Card ─────────────────────────────────────── */}
      <meta name="twitter:card"        content="summary_large_image" />
      <meta name="twitter:site"        content={TWITTER} />
      <meta name="twitter:creator"     content={TWITTER} />
      <meta name="twitter:title"       content={fullTitle} />
      <meta name="twitter:description" content={fullDesc} />
      <meta name="twitter:image"       content={OG_IMAGE} />

      {/* ── Schema.org JSON-LD ───────────────────────────────── */}
      <script type="application/ld+json">{`
        {
          "@context": "https://schema.org",
          "@type": "Person",
          "name": "Arshan Aslam",
          "url": "${SITE_URL}",
          "image": "${OG_IMAGE}",
          "jobTitle": "AI Engineer & Full-Stack Developer",
          "description": "${fullDesc}",
          "address": {
            "@type": "PostalAddress",
            "addressLocality": "Lahore",
            "addressCountry": "PK"
          },
          "email": "hello@arshanaslam.me",
          "sameAs": [
            "https://github.com/arshanaslam1",
            "https://linkedin.com/in/arshanaslam1",
            "https://blog.arshanaslam.me"
          ],
          "knowsAbout": [
            "Artificial Intelligence",
            "Machine Learning",
            "RAG Systems",
            "LangChain",
            "Django",
            "React",
            "Python",
            "Cloud Computing",
            "Full-Stack Development"
          ]
        }
      `}</script>
    </Helmet>
  );
}
