import React from "react";
import "./SkillGroup.css";

export default function SkillGroup({ icon, title, badge, skills }) {
  return (
    <div className="skill-group reveal">
      <div className="skill-group-header">
        <span className="skill-group-icon">{icon}</span>
        <span className="skill-group-title">{title}</span>
        {badge && <span className="skill-badge">{badge}</span>}
      </div>
      <div className="skill-tags">
        {skills.map((skill) => (
          <span
            key={skill.name}
            className={`skill-tag${skill.isNew ? " skill-tag--new" : ""}`}
          >
            {skill.name}
          </span>
        ))}
      </div>
    </div>
  );
}
